+/* Appends ".txt" if the file name has no extension. */
+void AddExt(TCHAR *sz)
+{
+    TCHAR *pch = sz + lstrlen(sz);
+    int    ch = *pch;
+
+    while (ch != TEXT('.') && ch != TEXT('\\') && ch != TEXT(':') && pch > sz) {
+        pch = CharPrev(sz, pch);
+        ch = *pch;
+    }
+
+    if (*pch != TEXT('.'))
+        lstrcat(sz, TEXT(".txt"));
+}

