+/* Copies szSrc to szDst, replacing the first chMerge sequence ("%%") with
+ * szMerge.  Returns TRUE if a merge took place. */
+BOOL MergeStrings(TCHAR *szSrc, TCHAR *szMerge, TCHAR *szDst)
+{
+    while (*szSrc != chMerge) {
+        *szDst++ = *szSrc;
+        if (!*szSrc++)
+            return FALSE;
+    }
+
+    if (szMerge) {
+        while (*szMerge)
+            *szDst++ = *szMerge++;
+    }
+    /* skip the two-character merge sequence */
+    szSrc++;
+    szSrc++;
+    while (*szDst++ = *szSrc++)
+        ;
+    return TRUE;
+}
