+int NpPrint(void)
+{
+    HDC     hPrintDC;
+    HANDLE  hText = NULL;
+    HANDLE  hLine;
+    HFONT   hPrintFont, hOldFont = NULL;
+    TEXTMETRIC tm;
+    TCHAR   szFaceName[32];
+    TCHAR   szTitle[MAX_PATH + 50];
+    DOCINFO di;
+    SIZE    size;
+    int     xPrintRes;
+    int     nLinesPerPage;
+    int     nPrinted;
+    int     iErr;
+    int     iLine, nLines;
+    int     ichLine, cch, iOffset;
+    int     y;
+    BOOL    fContinue;
+    DWORD   dwCharSet;
+    TCHAR  *pText, *pLine;
+    HDC     hdc;
