+/* Copies cch characters of pSrc to pDst expanding tabs (tab stops every
+ * 8 columns), wrapping every cchLine characters.  Returns the expanded
+ * length. */
+int ExpandTabs(TCHAR *pSrc, int cch, TCHAR *pDst, int cchLine)
+{
+    TCHAR buf[200];
+    int   total = 0;
+    int   col = 0, nextcol;
+    int   i;
+    for (i = 0; i < cch; i++) {
+        if (col >= cchLine) {
+            buf[cchLine] = 0;
+            lstrcpy(pDst, buf);
+            pDst += cchLine;
+            col = 0;
+        }
+        if (*pSrc == TEXT('\t')) {
+            nextcol = (col + 8) / 8 * 8;
+            if (nextcol > cchLine)
+                nextcol = cchLine;
+            if (col < nextcol)
+                memset(buf + col, ' ', nextcol - col);
+            total += nextcol - col;
+            col = nextcol;
+        } else {
+            buf[col++] = *pSrc;
+            total++;
+        }
+        pSrc++;
+    }
+    buf[col] = 0;
+    lstrcpy(pDst, buf);
+    return total;
+}
